<td align="left"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>576</mn><mi>L</mi></mrow><annotation encoding="application/x-tex">576L</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">576</span><span class="mord mathnormal">L</span></span></span></span></td>
